function SetMinSum(uint _val)  public nonReentrant_ {
       if(intitalized)revert();
       MinSum = add_uint256(MinSum, _val);
    }

modifier nonReentrant_() {
    require(locked_);
    locked_ = true;
    _;
    locked_ = false;
  }

function SetLogFile(address _log)  public nonReentrant_ {
        LogFile = Log(_log);
    }
